import { mergeProps, splitProps } from '@benosjs/dom'
import type { JSX } from '@benosjs/dom'

export type TextareaSize = 'sm' | 'md' | 'lg'

export type TextareaProps = Omit<JSX.IntrinsicElements['textarea'], 'class' | 'ref'> & {
  id?: string
  class?: string
  size?: TextareaSize
  invalid?: boolean
  ref?: (element: HTMLTextAreaElement) => void
}

export function Textarea(props: TextareaProps): JSX.Element {
  const merged = mergeProps({ size: 'md' as const, invalid: false }, props)
  const [local, native] = splitProps(merged, [
    'size',
    'class',
    'invalid',
    'ref',
    'children',
    'aria-invalid',
  ] as const)
  const ariaInvalid =
    local.invalid || local['aria-invalid'] === true || local['aria-invalid'] === 'true'
      ? 'true'
      : (local['aria-invalid'] ?? 'false')
  const ref = (element: HTMLTextAreaElement) => local.ref?.(element)

  return (
    <textarea
      {...native}
      class={['benos-textarea', 'benos-textarea--' + local.size, local.class]
        .filter(Boolean)
        .join(' ')}
      aria-invalid={ariaInvalid}
      data-invalid={ariaInvalid === 'true' ? 'true' : 'false'}
      ref={ref}
    >
      {local.children}
    </textarea>
  )
}

.benos-textarea {
  background: var(--benos-color-surface);
  border: 1px solid var(--benos-color-border);
  border-radius: var(--benos-radius-md);
  color: var(--benos-color-text);
  display: block;
  font: inherit;
  font-size: var(--benos-text-xs, 0.75rem);
  inline-size: 100%;
  min-block-size: 6rem;
  min-inline-size: 0;
  resize: vertical;
}

.benos-textarea--sm {
  padding: var(--benos-space-2);
}

.benos-textarea--md {
  padding: var(--benos-space-3);
}

.benos-textarea--lg {
  padding: var(--benos-space-4);
}

.benos-textarea::placeholder {
  color: var(--benos-color-text-muted);
  opacity: 1;
}

.benos-textarea:focus-visible {
  border-color: var(--benos-color-focus);
  outline: 3px solid var(--benos-color-focus);
  outline-offset: 2px;
}

.benos-textarea[aria-invalid='true'] {
  border-color: var(--benos-color-danger);
}

.benos-textarea:disabled {
  background: var(--benos-color-canvas);
  color: var(--benos-color-text-muted);
  cursor: not-allowed;
}
